mapper.select:
select


from t_gm_mail
where 1=1

    and create_time >= #{startTimer}


  and create_time <= #{endTimer}


    and mailOptType=#{mailOptType}


    and title like concat('%',#{title},'%')


    and context like concat('%',#{context},'%')



  and opt_flag = #{status}

order by create_time desc
limit #{limit}, #{offset}
